export class Weapon {
    /**
     * Create a weapon proxy instance.
     *
     * @param {Object} views - SharedArrayBuffer views { weapons, projectiles }
     * @param {string} type - Weapon type ('hitscan', 'projectile', 'hybrid')
     * @param {number} index - Weapon slot index
     * @param {THREE.Mesh} [mesh=null] - Optional visual mesh for projectiles
     * @param {Physics} [physics=null] - Physics instance reference
     * @param {Object} [properties={}] - Weapon configuration properties
     */
    constructor(views: any, type: string, index: number, mesh?: THREE.Mesh, physics?: Physics, properties?: any);
    _views: any;
    _type: string;
    _index: number;
    _mesh: THREE.Mesh;
    _physics: Physics;
    _properties: any;
    _listeners: {};
    _registeredEvents: Set<any>;
    _getBuffer: () => any;
    /**
     * Add an event listener.
     *
     * @param {string} type - Event type (use WeaponEvent constants)
     * @param {Function} listener - Event handler function
     * @example
     * weapon.addEventListener(WeaponEvent.HIT, (event) => {
     *   console.log('Hit at:', event.hitPoint);
     * });
     */
    addEventListener(type: string, listener: Function): void;
    /**
     * Remove an event listener.
     *
     * @param {string} type - Event type
     * @param {Function} listener - Event handler function to remove
     */
    removeEventListener(type: string, listener: Function): void;
    /**
     * Dispatch an event to all registered listeners.
     *
     * @param {Object} event - Event object with type and data
     * @private
     */
    private dispatchEvent;
    /**
     * Fire weapon from body position.
     *
     * @param {number|Object} shooter - Body index or body API object (from physics.addBody)
     * @param {Object} [options={}] - Fire options
     * @param {THREE.Vector3|Array<number>} [options.origin] - Custom origin as Vector3 or [x, y, z]
     * @param {THREE.Vector3|Array<number>} options.direction - Fire direction as Vector3 or [x, y, z] (required)
     * @example
     * // Using body API directly (recommended)
     * weapon.fire(playerApi, { direction: aimDir });
     *
     * // Using Vector3
     * weapon.fire(playerApi, { origin: muzzlePos, direction: aimDirection });
     *
     * // Using body index (legacy)
     * weapon.fire(playerApi.index, { bodyType: 'dynamic', direction: [0, 0, -1] });
     */
    fire(shooter: number | any, options?: {
        origin?: THREE.Vector3 | Array<number>;
        direction: THREE.Vector3 | Array<number>;
    }): void;
    /**
     * Fire weapon from camera position and direction.
     *
     * @param {Object} [options={}] - Fire options
     * @example
     * weapon.fireFromCamera();
     */
    fireFromCamera(options?: any): void;
    /**
     * Set weapon damage value.
     * @type {number}
     */
    set damage(value: number);
    /**
     * Get weapon damage value.
     * @type {number}
     */
    get damage(): number;
    /**
     * Get weapon index.
     * @type {number}
     * @readonly
     */
    readonly get index(): number;
    /**
     * Get weapon type.
     * @type {string}
     * @readonly
     */
    readonly get type(): string;
    /**
     * Get associated mesh (or first mesh from pool for projectile weapons).
     * @type {THREE.Mesh}
     * @readonly
     */
    readonly get mesh(): THREE.Mesh;
    /**
     * Get mesh pool (for projectile weapons with multiple projectiles).
     * Must be an InstancedMesh created via physics.createMeshPool().
     * @type {THREE.InstancedMesh|null}
     * @readonly
     */
    readonly get meshPool(): THREE.InstancedMesh | null;
    /**
     * Register event type with worker thread.
     * Called automatically on first addEventListener.
     *
     * @param {string} eventType - Event type to register
     * @private
     */
    private _registerEventWithWorker;
    /**
     * Unregister event type from worker thread.
     * Called automatically when last listener is removed.
     *
     * @param {string} eventType - Event type to unregister
     * @private
     */
    private _unregisterEventFromWorker;
    /**
     * Dispose weapon and clean up resources.
     * Removes all event listeners and mesh associations.
     * Called automatically by Physics.removeWeapon().
     *
     * @example
     * ```javascript
     * // Usually called via physics.removeWeapon()
     * await physics.removeWeapon(weaponApi);
     *
     * // Can also be called directly if needed
     * weaponApi.weapon.dispose();
     * ```
     */
    dispose(): void;
}
